// Simple endless runner based on IDEA.md
// Canvas with id="game"
(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  const width = canvas.width = canvas.offsetWidth || 800;
  const height = canvas.height = canvas.offsetHeight || 200;

  const player = {
    x: 50,
    y: height - 30,
    w: 20,
    h: 30,
    vy: 0,
    jumpStrength: -8,
    onGround: true,
    draw() { ctx.fillStyle = '#4CAF50'; ctx.fillRect(this.x, this.y, this.w, this.h); },
    update() {
      this.vy += 0.4; // gravity
      this.y += this.vy;
      if (this.y + this.h >= height) { this.y = height - this.h; this.vy = 0; this.onGround = true; } else { this.onGround = false; }
    },
    jump() { if (this.onGround) { this.vy = this.jumpStrength; this.onGround = false; } }
  };

  // obstacles: simple rectangles moving left
  const obstacles = [];
  let obstacleTimer = 0;
  const obstacleInterval = 120; // frames
  let score = 0;
  let gameOver = false;

  function spawnObstacle() {
    const w = 20 + Math.random() * 20;
    const h = 20 + Math.random() * 40;
    obstacles.push({ x: width, y: height - h, w, h, passed: false });
  }

  function updateObstacles() {
    for (let i = obstacles.length - 1; i >= 0; i--) {
      const o = obstacles[i];
      o.x -= 3; // speed
      // collision
      if (!gameOver &&
          player.x < o.x + o.w &&
          player.x + player.w > o.x &&
          player.y < o.y + o.h &&
          player.y + player.h > o.y) {
        gameOver = true;
      }
      // remove off‑screen
      if (o.x + o.w < 0) obstacles.splice(i, 1);
    }
  }

  function drawObstacles() {
    ctx.fillStyle = '#D32F2F';
    obstacles.forEach(o => ctx.fillRect(o.x, o.y, o.w, o.h));
  }

  function drawScore() {
    ctx.fillStyle = '#000';
    ctx.font = '16px sans-serif';
    ctx.fillText('Score: ' + score, 10, 20);
  }

  function loop() {
    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.5)';
      ctx.fillRect(0,0,width,height);
      ctx.fillStyle = '#fff';
      ctx.font = '24px sans-serif';
      ctx.fillText('Game Over', width/2-60, height/2);
      return;
    }
    ctx.clearRect(0,0,width,height);
    player.update();
    player.draw();
    obstacleTimer++;
    if (obstacleTimer > obstacleInterval) { spawnObstacle(); obstacleTimer = 0; }
    updateObstacles();
    drawObstacles();
    score++;
    drawScore();
    requestAnimationFrame(loop);
  }

  canvas.addEventListener('click', () => player.jump());
  // also support touch
  canvas.addEventListener('touchstart', e => { e.preventDefault(); player.jump(); });

  loop();
})();
